internal.body:
if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
if (mode == 1) return 30.0;
if (mode == 2) return 60.0;
return 90.0;

if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
if (mode == 1) fan.setLow();
else if (mode == 2) fan.setMedium();
else fan.setHigh();

upMode.body:
try {
  if (currentMode >= MAX_MODE) return false;
  setSpeedByMode(currentMode + 1);
  currentMode++;
} catch(Exception e) {
  return false;
}
return true;

downMode.body:
try {
  if (currentMode <= 1) return false;
  setSpeedByMode(currentMode - 1);
  currentMode--;
} catch(Exception e) {
  return false;
}
return true;

setMode.body:
try {
  if (modeIndex <= 0 || modeIndex > MAX_MODE) return false;
  setSpeedByMode(modeIndex);
  currentMode = modeIndex;
} catch(Exception e) {
  return false;
}
return true;

suspend.body:
try {
  fan.turnOff();
  isSuspended = true;
} catch(Exception e) {
  return false;
}
return true;

resume.body:
try {
  if (fan.getState() == fr.sorbonne_u.components.hem2025e1.equipments.fan.FanImplementationI.FanState.OFF) {
    fan.turnOn();
  }
  setSpeedByMode(currentMode);
  isSuspended = false;
} catch(Exception e) {
  return false;
}
return true;
